package solution

import "sort"

func ResolvePermissions(role string, parents map[string]string, grants map[string][]string) ([]string, bool) {
	if role == "" {
		return nil, false
	}

	// Check if the role exists
	if _, ok := parents[role]; !ok {
		return nil, false
	}

	// Build the set of all grants from the role and its ancestors
	var allGrants []string
	seen := make(map[string]bool)

	// Start with the given role
	currentRole := role
	seen[currentRole] = true

	// Traverse up the parent chain
	for {
		parent, ok := parents[currentRole]
		if !ok {
			// Unknown parent reached
			return nil, false
		}

		// If parent is empty, it's the root
		if parent == "" {
			break
		}

		// Check for cycles
		if seen[parent] {
			return nil, false
		}
		seen[parent] = true

		// Add parent's grants
		for _, grant := range parents[parent] {
			allGrants = append(allGrants, grant)
		}

		currentRole = parent
	}

	// Sort the grants
	sort.Strings(allGrants)

	return allGrants, true
}

